import { delegate, type SafeHtml } from 'kerfjs';
import { MenuHeader } from '@kerfjs/ui/menu-header';
import { MenuItem } from '@kerfjs/ui/menu-item';
import { Toolbar } from '@kerfjs/ui/toolbar';
import { ToolbarControlGroup } from '@kerfjs/ui/toolbar-control-group';
import { LucideIcon } from '@kerfjs/ui/lucide-icon';
import { Inbox, Folder, Plus, Settings } from 'lucide';
import '@kerfjs/ui/layout.css';
import '@kerfjs/ui/sidebar.css';
import './navigation.css';

type Destination = 'inbox' | 'drafts' | 'projects';
export function mountNavigation(root: HTMLElement, app: {
  renderInto(root: HTMLElement, view: SafeHtml): void;
  navigate(destination: Destination): void;
  addProject(): void;
  openSettings(): void;
}) {
  let selected: Destination = 'inbox';
  function render() {
    app.renderInto(root, <aside class="navigation kui-layout" aria-label="Workspace sidebar">
      <nav class="kui-sidebar navigation-content kui-scroll-owner" aria-label="Workspace sections">
        <section class="kui-sidebar-section">
          <MenuHeader label="Workspace" />
          <MenuItem label="Inbox" action="navigation.open" itemId="inbox"
            icon={<LucideIcon icon={Inbox} name="inbox" />} selected={selected === 'inbox'} trailing={<span>12</span>} />
          <MenuItem label="Drafts" action="navigation.open" itemId="drafts" selected={selected === 'drafts'} />
        </section>
        <section class="kui-sidebar-section">
          <MenuHeader label="Projects" />
          <MenuItem label="Active projects" action="navigation.open" itemId="projects"
            icon={<LucideIcon icon={Folder} name="folder" />} selected={selected === 'projects'} />
          <MenuItem label="Archived projects" action="navigation.open" itemId="archive"
            disabled title="Administrator access required" trailing={<span>Admin only</span>} multiline />
          <div class="kui-sidebar-surface">
            <strong>Design workspace</strong>
            <p>8 active projects · 12 members</p>
            <p>Quarterly goal: make every workspace usable by keyboard.</p>
          </div>
        </section>
      </nav>
      <footer class="navigation-footer kui-sidebar">
        <Toolbar label="Workspace utilities" divider={false}
          leading={<ToolbarControlGroup appearance="borderless" single>
            <button type="button" aria-label="Add project" data-action="navigation.add"><LucideIcon icon={Plus} name="plus" /></button>
          </ToolbarControlGroup>}
          trailing={<ToolbarControlGroup appearance="borderless" single>
            <button type="button" aria-label="Workspace settings" data-action="navigation.settings"><LucideIcon icon={Settings} name="settings" /></button>
          </ToolbarControlGroup>} />
      </footer>
    </aside>);
  }
  render();
  const dispose = delegate(root, 'click', '[data-action]', (_event, element) => {
    const node = element as HTMLElement;
    if (node.dataset.action === 'navigation.open') {
      const id = node.dataset.itemId;
      if (id !== 'inbox' && id !== 'drafts' && id !== 'projects') return;
      selected = id; app.navigate(id); render();
    } else if (node.dataset.action === 'navigation.add') app.addProject();
    else if (node.dataset.action === 'navigation.settings') app.openSettings();
  });
  return dispose;
}

