.navigation { display: grid; grid-template-rows: minmax(0, 1fr) auto; block-size: 100%; min-height: 0; min-width: 0; color: var(--kui-color-text); background: var(--kui-color-surface); }
.navigation-content { padding-block: var(--kui-layout-pane-inset); min-height: 0; overflow-wrap: anywhere; }
